    #[test]
    fn typechecker_pass_coverage_matrix_classifies_stmt_and_type_decl_variants() {
        let rows = typechecker_pass_coverage_cases();
        let expected_stmt_variants: BTreeSet<_> = [
            "Defn",
            "TypeDecl",
            "Rule",
            "Use",
            "Import",
            "QualifiedImport",
            "HashImport",
            "Depend",
            "RustBlock",
            "Annot",
            "Bind",
            "MonadicBind",
            "For",
            "While",
            "Send",
            "StreamBind",
            "StreamSub",
            "Invariant",
            "Prove",
            "Assert",
            "Retract",
            "Abort",
            "Expr",
        ]
        .into_iter()
        .collect();
        let observed_stmt_variants: BTreeSet<_> = rows
            .iter()
            .map(|row| typechecker_stmt_variant_label(&row.stmt))
            .collect();
        assert_eq!(observed_stmt_variants, expected_stmt_variants);

        let expected_type_decl_variants: BTreeSet<_> = [
            "ADT",
            "WhenType",
            "EffectDecl",
            "TraitDecl",
            "ImplBlock",
            "RuleScope",
        ]
        .into_iter()
        .collect();
        let observed_type_decl_variants: BTreeSet<_> = rows
            .iter()
            .filter_map(|row| match &row.stmt {
                Stmt::TypeDecl(decl) => Some(typechecker_type_decl_variant_label(decl)),
                _ => None,
            })
            .collect();
        assert_eq!(observed_type_decl_variants, expected_type_decl_variants);

        for row in &rows {
            assert_eq!(
                typechecker_stmt_coverage(&row.stmt),
                row.coverage,
                "typechecker pass coverage classification mismatch for {}",
                row.label
            );

            let mut checker = TypeChecker::new();
            checker.check_stmt(&row.stmt);
            for marker in &row.diagnostic_markers {
                assert!(
                    checker
                        .diagnostics
                        .iter()
                        .any(|diag| diag.message.contains(marker)),
                    "typechecker traversal missed `{}` in {}; diagnostics: {:?}",
                    marker,
                    row.label,
                    checker.diagnostics
                );
            }
        }
    }

    fn collect_ast_visitor_vars_from_expr(expr: &Expr, vars: &mut BTreeSet<String>) {
        walk_ast_expr(expr, &mut |child| {
            if let AstChild::Expr(expr) = child {
                if let ExprKind::Var(name) = &expr.kind {
                    vars.insert(name.clone());
                }
            }
        });
    }

    fn collect_ast_visitor_vars_from_stmt(stmt: &Stmt, vars: &mut BTreeSet<String>) {
        walk_ast_stmt(stmt, &mut |child| {
            if let AstChild::Expr(expr) = child {
                if let ExprKind::Var(name) = &expr.kind {
                    vars.insert(name.clone());
                }
            }
        });
    }

    #[test]
    fn canonical_ast_walk_reaches_pass_coverage_markers() {
        for row in typechecker_pass_coverage_cases() {
            let mut vars = BTreeSet::new();
            collect_ast_visitor_vars_from_stmt(&row.stmt, &mut vars);
            for marker in row.diagnostic_markers {
                assert!(
                    vars.contains(marker),
                    "canonical AST visitor missed `{}` in {}; visited {:?}",
                    marker,
                    row.label,
                    vars
                );
            }
        }
    }

    #[test]
    fn typechecker_diagnostic_has_span() {
        let source = "> main() -> Int { xyz(1) }";
        let diags = check_source_for_diagnostics(source);
        assert!(!diags.is_empty());
        assert!(
            diags[0].span.is_some(),
            "expected span on type error diagnostic"
        );
    }

